<?php require __DIR__.'/../config/database.php';if(empty($_SESSION['admin_id'])){header('Location: login.php');exit;}
$msg='';$err='';
if($_SERVER['REQUEST_METHOD']==='POST'){$action=$_POST['action']??'';if(!hash_equals($_SESSION['csrf_admin']??'',$_POST['csrf']??'')){$err='Sesi berubah. Muat ulang halaman.';}elseif($action==='status'){$id=(int)($_POST['booking_id']??0);$status=$_POST['status']??'';$pay=$_POST['payment_status']??'';$allowed=['Menunggu','Dikonfirmasi','Selesai','Dibatalkan'];$payments=['Belum Bayar','DP','Lunas'];if(in_array($status,$allowed,true)&&in_array($pay,$payments,true)){$s=$conn->prepare('UPDATE bookings SET status=?,payment_status=? WHERE id=?');$s->bind_param('ssi',$status,$pay,$id);$s->execute();$msg='Status booking diperbarui.';}}elseif($action==='package'){$id=(int)($_POST['package_id']??0);$price=max(0,(float)($_POST['price']??0));$active=isset($_POST['is_active'])?1:0;$s=$conn->prepare('UPDATE packages SET price=?,is_active=? WHERE id=?');$s->bind_param('dii',$price,$active,$id);$s->execute();$msg='Paket diperbarui.';}}
if(!isset($_SESSION['csrf_admin']))$_SESSION['csrf_admin']=bin2hex(random_bytes(32));
$stats=$conn->query("SELECT COUNT(*) total, SUM(status='Menunggu') waiting, SUM(status='Dikonfirmasi') confirmed, SUM(payment_status='Lunas') paid FROM bookings")->fetch_assoc();$revenue=$conn->query("SELECT COALESCE(SUM(total_price),0) n FROM bookings WHERE status IN ('Dikonfirmasi','Selesai')")->fetch_assoc()['n'];$bookings=$conn->query('SELECT b.*,p.name package_name FROM bookings b JOIN packages p ON p.id=b.package_id ORDER BY b.created_at DESC LIMIT 250')->fetch_all(MYSQLI_ASSOC);$packages=$conn->query('SELECT * FROM packages ORDER BY name')->fetch_all(MYSQLI_ASSOC);$tab=$_GET['tab']??'bookings';
?><!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Dashboard Admin — Nusindo Wisata</title><link rel="stylesheet" href="../assets/css/style.css"></head><body><div class="admin-wrap"><aside class="sidebar"><a class="brand" href="../index.php" style="color:white"><span class="brand-mark">N</span>Nusindo</a><a class="side-link <?=$tab==='bookings'?'active':''?>" href="dashboard.php?tab=bookings">▤ Pemesanan</a><a class="side-link <?=$tab==='packages'?'active':''?>" href="dashboard.php?tab=packages">◇ Paket wisata</a><a class="side-link" href="logout.php">↪ Keluar</a></aside><main class="admin-main"><div class="admin-top"><div><div class="kicker">Panel pengelola</div><h1>Halo, <?=e($_SESSION['admin_name']??'Admin')?> 👋</h1><p class="muted" style="margin:5px 0">Ringkasan dan pengelolaan Nusindo Wisata.</p></div><a class="btn btn-light" href="../index.php" target="_blank">Lihat Website ↗</a></div><?php if($msg):?><div class="notice"><?=e($msg)?></div><?php endif;?><?php if($err):?><div class="notice error"><?=e($err)?></div><?php endif;?>
<div class="stats"><div class="stat"><span>Total booking</span><strong><?=number_format((int)$stats['total'])?></strong></div><div class="stat"><span>Menunggu konfirmasi</span><strong><?=number_format((int)$stats['waiting'])?></strong></div><div class="stat"><span>Dikonfirmasi</span><strong><?=number_format((int)$stats['confirmed'])?></strong></div><div class="stat"><span>Estimasi nilai booking terkonfirmasi</span><strong style="font-size:1.1rem"><?=rupiah($revenue)?></strong></div></div>
<?php if($tab==='packages'):?><div class="admin-top"><h2>Kelola paket wisata</h2><span class="muted">Harga estimasi per orang dan visibilitas paket</span></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Paket</th><th>Destinasi</th><th>Durasi</th><th>Harga/orang</th><th>Aktif</th><th>Aksi</th></tr></thead><tbody><?php foreach($packages as $p):?><tr><form method="post"><input type="hidden" name="csrf" value="<?=e($_SESSION['csrf_admin'])?>"><input type="hidden" name="action" value="package"><input type="hidden" name="package_id" value="<?=$p['id']?>"><td><strong><?=e($p['name'])?></strong></td><td><?=e($p['destination'])?></td><td><?=e($p['duration'])?></td><td><input style="width:140px;padding:8px;border:1px solid #dce6df;border-radius:8px" type="number" min="0" step="1000" name="price" value="<?=e($p['price'])?>" required></td><td><input type="checkbox" name="is_active" value="1" <?=$p['is_active']?'checked':''?> aria-label="Paket aktif"></td><td><button class="small-btn">Simpan</button></td></form></tr><?php endforeach;?></tbody></table></div>
<?php else:?><div class="admin-top"><h2>Daftar pemesanan</h2><span class="muted">Maksimal 250 booking terbaru</span></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Kode / Waktu</th><th>Pelanggan</th><th>Paket</th><th>Keberangkatan</th><th>Peserta</th><th>Total</th><th>Status & pembayaran</th><th>Simpan</th></tr></thead><tbody><?php if(!$bookings):?><tr><td colspan="8">Belum ada booking masuk.</td></tr><?php endif;?><?php foreach($bookings as $b):?><tr><form method="post"><input type="hidden" name="csrf" value="<?=e($_SESSION['csrf_admin'])?>"><input type="hidden" name="action" value="status"><input type="hidden" name="booking_id" value="<?=$b['id']?>"><td><strong><?=e($b['booking_code'])?></strong><br><small><?=e($b['created_at'])?></small></td><td><strong><?=e($b['customer_name'])?></strong><br><small><?=e($b['email'])?><br><?=e($b['phone'])?></small><?php if($b['notes']):?><br><small>Catatan: <?=e($b['notes'])?></small><?php endif;?></td><td><?=e($b['package_name'])?></td><td><?=e($b['departure_date'])?></td><td><?=e($b['participants'])?></td><td><strong><?=rupiah($b['total_price'])?></strong></td><td><select name="status" style="padding:7px;border:1px solid #dce6df;border-radius:8px;margin-bottom:6px"><?php foreach(['Menunggu','Dikonfirmasi','Selesai','Dibatalkan'] as $s):?><option <?=$b['status']===$s?'selected':''?>><?=$s?></option><?php endforeach;?></select><br><select name="payment_status" style="padding:7px;border:1px solid #dce6df;border-radius:8px"><?php foreach(['Belum Bayar','DP','Lunas'] as $s):?><option <?=$b['payment_status']===$s?'selected':''?>><?=$s?></option><?php endforeach;?></select></td><td><button class="small-btn">Update</button></td></form></tr><?php endforeach;?></tbody></table></div><?php endif;?></main></div></body></html>
